// Service Worker — AirNubeiro ACARS PWA v5.5.1
// Red primero para la app (las actualizaciones se ven al instante) y
// caché solo como respaldo offline. Nunca cachea APIs ni el proxy local.
const CACHE_NAME = 'an-acars-v5.5.1';
const APP_SHELL = ['./', './index.html', './ops-center.html', './nbv-core.js', './nbv-ui.css', './manifest.json', './icons/nbv-mark.png', './icons/icon-192.png', './icons/icon-512.png'];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE_NAME).then(c => c.addAll(APP_SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== CACHE_NAME).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// 5.4.0-rc.2: el navegador rechaza una respuesta con redirección servida a una navegación («a redirected response was used
// for a request whose redirect mode is not "follow"»), p. ej. ops-center.html → /ops-center de Cloudflare. Se reconstruye limpia.
const clean = resp => resp && resp.redirected
  ? resp.blob().then(b => new Response(b, { status: resp.status, statusText: resp.statusText, headers: resp.headers }))
  : resp;

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // APIs externas, proxy local y health: siempre red, sin tocar caché
  if (url.origin !== self.location.origin || url.pathname.startsWith('/proxy') || url.pathname.startsWith('/__nbv')) return;
  // 5.5.1: tampoco el TechLog (estado vivo del avión), lo pedido sin caché (version.json?t=…) ni un recurso con consulta
  // (una entrada de caché nueva por cada una). Una navegación con consulta (ops-center.html?embed=1) sí: es la app, y sin red se sirve de la caché.
  if (url.pathname.startsWith('/techlog')) return;
  if (req.cache === 'no-store') return;
  if (url.search && req.mode !== 'navigate') return;
  e.respondWith(
    fetch(req).then(clean).then(resp => {
      if (resp.ok) { const copy = resp.clone(); caches.open(CACHE_NAME).then(c => c.put(req, copy)); }
      return resp;
    }).catch(() => caches.match(req).then(c => c ? clean(c) : (req.mode === 'navigate'
      // 5.5.1: una navegación con consulta que nunca se pidió con red (ops-center.html?embed=1) se sirve de la página sin consulta, no del ACARS
      ? caches.match(req, { ignoreSearch: true }).then(m => m ? clean(m) : caches.match('./index.html').then(clean)).then(i => i || Response.error())
      : Response.error())))
  );
});
